/// One way a module exports a component (ADR 0027): under an export name, or, for a sub-component attached to an
/// exported component, through properties of that export.
///
/// `export function Card` is `Card`, `export { _Card as Card }` is `Card`, `export default Menu` is `default`, and
/// `Menu.Item = Item` beside it is `default.Item`: the path starts at the name the module exports the parent under, not
/// at the parent's local name, so a reader can follow it from the module.
#[derive(Debug, Clone, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize)]
pub struct ComponentExport {
    /// The export name: `default` for the default export.
    pub name: std::string::String,
    /// The properties, outermost first, through which an attached sub-component is reached from the export; empty for
    /// the export itself.
    pub members: Vec<std::string::String>,
}

impl ComponentExport {
    /// The export `name` itself.
    pub fn named(name: impl Into<std::string::String>) -> Self {
        Self { name: name.into(), members: Vec::new() }
    }

    /// The property `member` of this export: where a sub-component attached under that name is reached.
    #[must_use]
    pub fn member(&self, member: impl Into<std::string::String>) -> Self {
        let mut members = self.members.clone();
        members.push(member.into());
        Self { name: self.name.clone(), members }
    }
}

impl std::fmt::Display for ComponentExport {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.name)?;
        for member in &self.members {
            write!(f, ".{member}")?;
        }
        Ok(())
    }
}

/// A component → prop type mapping.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ComponentMapping {
    /// The component's name as the extractor found it.
    pub component_name: std::string::String,
    /// The name of the type that holds its props, which the resolver looks up.
    pub props_type_name: TypeName,
    /// The type arguments given to the props type, in order.
    pub props_type_args: Vec<CollectedType>,
    /// The file that declares the component.
    pub file_path: Utf8PathBuf,
    /// The component's JSDoc description, empty when it has none.
    pub description: std::string::String,
    /// The component's JSDoc tags: tag name (without the `@`) to the text after it; a `@param name` is keyed
    /// `param:name`.
    pub tags: BTreeMap<std::string::String, std::string::String>,
    /// Byte span for diagnostics
    pub span_start: u32,
    /// The end of the span that starts at `span_start`, in bytes.
    pub span_end: u32,
    /// Default values extracted from parameter destructuring or defaultProps.
    /// Key = prop name. Populated only for implementation files (.tsx/.ts), not .d.ts.
    pub param_defaults: FxHashMap<std::string::String, RawDefault>,
    /// Which extractor rule matched.
    pub rule: DetectionRule,
    /// How its module exports it, in source order: each export name, or for a sub-component attached to an exported
    /// component the path through that export. Empty when the module does not export it.
    pub exports: Vec<ComponentExport>,
    /// For a component built by a generic call (`WrapperTypeArgument`, or a `HocWrapper` call with type arguments),
    /// that call: its result type can add props the selected props type lacks.
    pub wrapper_callee: Option<WrapperCallee>,
    /// The type parameters of the functions the declaration contains (`function ActionBar<T extends object>(props:
    /// ActionBarProps<T>)`): placeholders in the props type, not unresolvable names.
    pub type_params: Vec<TypeName>,
}

impl ComponentMapping {
    /// A mapping with no type arguments, documentation or parameter defaults; add them with the `with_*` methods.
    pub fn new(
        component_name: std::string::String,
        props_type_name: TypeName,
        file_path: Utf8PathBuf,
        span_start: u32,
        span_end: u32,
        rule: DetectionRule,
    ) -> Self {
        Self {
            component_name,
            props_type_name,
            props_type_args: Vec::new(),
            file_path,
            description: std::string::String::new(),
            tags: BTreeMap::new(),
            span_start,
            span_end,
            param_defaults: FxHashMap::default(),
            rule,
            exports: Vec::new(),
            wrapper_callee: None,
            type_params: Vec::new(),
        }
    }

    /// Whether this is the component the module's binding `name` declares. An inline sub-component
    /// (`Parent.Name = (props: P) => …`) has the name but no binding, and another component can have the binding.
    pub fn is_binding_named(&self, name: &str) -> bool {
        self.rule != DetectionRule::AttachedSubComponent && self.component_name == name
    }

    /// Whether its module exports it, directly or as a sub-component attached to an exported component.
    pub fn exported(&self) -> bool {
        !self.exports.is_empty()
    }

    /// The mapping of no component, for a question about a type asked mid-walk (what a named type's props are, for a
    /// property read): it has no parameter defaults, wrapper call or type parameters of its own to bring.
    pub(crate) fn of_no_component(file_path: &camino::Utf8Path) -> Self {
        Self::new(
    pub html_element: Option<String>,
    /// Number of props this layer contributes (for display).
    pub total_props: u32,
    /// For a collapsed source, the names of the props it declares, which the output otherwise leaves out (only the
    /// notable ones are listed as props). Empty for a layer whose props are expanded.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub members: Vec<String>,
}

/// A single React component with its resolved props.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ComponentEntry {
    /// Display name of the component
    pub display_name: String,
    /// Absolute path of the file containing the component
    pub file_path: Utf8PathBuf,
    /// Component-level JSDoc description
    pub description: String,
    /// Resolved props, keyed by prop name. Shared: components that inherit one interface hold the same prop, so change
    /// one through `Arc::make_mut`, which copies it first when another component holds it too.
    pub props: BTreeMap<String, Arc<ParsedProp>>,
    /// Full resolved inheritance chain, outermost first.
    pub inheritance: Vec<InheritedLayer>,
    /// Curated notable props from inherited layers (not in self.props), shared like `props`.
    pub notable_inherited: BTreeMap<String, Arc<ParsedProp>>,
    /// If props type is a discriminated union, the name of the discriminant prop (e.g. "variant").
    pub discriminant_prop: Option<String>,
    /// Type names that could not be resolved (react-docgen compat)
    pub composes: Vec<String>,
    /// JSDoc @tags on the component (e.g. @deprecated, @since)
    pub tags: BTreeMap<String, String>,
    /// Always empty for functional components; present for RDT compat
    pub methods: Vec<()>,
    /// The extractor rule that recognized this component. `typedFunctionExpression` and `wrapperTypeArgument` are
    /// inferred from a function's shape and what it returns; the others are explicit declaration forms.
    pub detected_by: crate::types::DetectionRule,
    /// Whether its module exports it, directly or as a sub-component attached to an exported component. An unexported
    /// component is an implementation detail other components render; RDT does not report those.
    pub exported: bool,
    /// How its module exports it ([`crate::types::ComponentMapping::exports`]); `exported` is whether it has any. The
    /// TypeScript checker asks for the component by these. Not in the canonical JSON yet, so an output read back from
    /// JSON has none.
    #[serde(skip)]
    pub exports: Vec<crate::types::ComponentExport>,
}

impl ComponentEntry {
    /// Shortcut: the HTML element this component renders as, if any.
    /// Derived from the inheritance chain.
    pub fn html_element(&self) -> Option<&str> {
        self.inheritance.iter().find_map(|l| l.html_element.as_deref())
    }
}

